        code = "\n".join(code)

    # Simplified regex-based syntax highlighting simulation to match highr logic
    # Keywords, Strings, Comments
    res = code
    # This is a simplified simulation of the internal hilight_one
    if format_val == "latex":
        res = res.replace("#", cmd_latex.loc["COMMENT", "start"] + escape_latex("#") + cmd_latex.loc["COMMENT", "end"])
    else:
        res = res.replace("#", cmd_html.loc["COMMENT", "start"] + escape_html("#") + cmd_html.loc["COMMENT", "end"])

    return res

def raw_string(x):
    return x

def valid_syntax(code, silent=False):
    return True

def split_source(code):
    if isinstance(code, str):
        return [code]
    return code

def hilight(code, format_val="latex", markup=None, prompt=False, fallback=False):
    if not code or (isinstance(code, list) and len(code) == 0):
        return raw_string(code)

    if markup is None:
        markup = cmd_latex if format_val == "latex" else cmd_html

    escape_fun = escape_latex if format_val == "latex" else escape_html

    if not fallback and not valid_syntax(code):
        import warnings
        warnings.warn("the syntax of the source code is invalid; the fallback mode is used")
        fallback = True

    if not prompt:
        # Simplified: use hilight_one directly
        return raw_string(hilight_one(code, format_val, markup, escape_fun))

    # Prompt logic
    p1 = escape_fun(">") # Default R prompt
    p2 = escape_fun("+") # Default R continue
    std = markup.loc["DEFAULT"].values
    if not any(pd.isna(std)):
        p1 = f"{std[0]}{p1}{std[1]}"
        p2 = f"{std[0]}{p2}{std[1]}"

    code_split = split_source(code)
    res = []
    for item in code_split:
        highlighted = hilight_one(item, format_val, markup, escape_fun)
        if isinstance(highlighted, list):
            lines = highlighted
        else:
            lines = [highlighted]

        formatted_lines = [p1] + [p2] * (len(lines) - 1)
        # Note: logic here is a simplified representation of the R mapply/sapply
        res.append("\n".join([f"{p} {l}" for p, l in zip(formatted_lines, lines)]))

    return raw_string(res)

def hi_latex(code, **kwargs):
    return hilight(code, "latex", **kwargs)

def hi_html(code, **kwargs):
    return hilight(code, "html", **kwargs)

